// Índice por categoría para búsqueda eficiente
export const HERRAMIENTAS_POR_CATEGORIA = HERRAMIENTAS.reduce<Record<string, Herramienta[]>>(
  (acc, h) => {
    h.categorias.forEach((cat) => {
      if (!acc[cat]) acc[cat] = [];
      acc[cat].push(h);
    });
    return acc;
  },
  {}
);

export const TOTAL_HERRAMIENTAS = HERRAMIENTAS.length;
